INSERT IGNORE INTO graha_bhava_rashi (graha_id, bhava_id, rashi_id, interpretation_np, interpretation_en, positive_effects, challenges, career_indication, financial_indication, relationship_indication, classical_interpretation, sanskrit_reference, remedies) VALUES
(1,1,1,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, साहस','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, जल्दबाजी','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, सेना','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, आत्मप्रयासबाट आय','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, ऊर्जावान तर धैर्य कम','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,2,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, धैर्य','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, जिद','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, कृषि','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, बचत र भूमि लाभ','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, वफादार र शान्त','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,3,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, वाणी','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, द्विधा','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, लेखन','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, बहुआय','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, मैत्रीपूर्ण तर भावना चञ्चल','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,4,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, करुणा','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, मनोद्वन्द्व','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, खाद्य','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, चल सम्पत्ति','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, गहिरो स्नेह र ममता','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,5,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, नेतृत्व','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, दम्भ','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, कला','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, उदार खर्चसँगै प्रतिष्ठाजनक आय','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, आदर चाहने, उदार','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,6,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, विश्लेषण','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, आलोचनात्मकता','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, चिकित्सा','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, योजनाबद्ध बचत','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, व्यावहारिक स्नेह, सेवा','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,7,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, न्याय','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, निर्णय ढिलाइ','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, कानुन','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, सन्तुलित आय','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, सामञ्जस्यपूर्ण जीवनसाथी','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,8,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, अन्तर्दृष्टि','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, षड्यन्त्रवाद','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, अनुसन्धान','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, अचानक उतारचढाव','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, गहिरो तर तीव्र','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,9,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, ज्ञान','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, अति विश्वास','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, शिक्षण','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, भाग्यबाट लाभ','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, स्वतन्त्रता दिने','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,10,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, कर्मठता','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, निराशावाद','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, व्यवस्थापन','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, हौले हौले सम्पत्ति','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, जिम्मेवार तर शब्द कम','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,11,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, नवप्रवर्तन','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, विद्रोहीपन','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, प्रविधि','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, नवीन तर अनियमित स्रोत','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, मित्रतामा आधारित','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,1,12,'सूर्य लग्नमा रहँदा व्यक्ति आत्मविश्वासी र नेतृत्वमा सक्षम हुन्छ। शारीरिक रूप बलियो र ऊर्ध्वाधर हुन्छ। आफ्नो अधिकारमा विश्वास गर्ने प्रकृति देखिन्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'आत्मविश्वास, नेतृत्व गुण, सार्वजनिक सम्मान, ऊर्जावान शरीर, कल्पनाशक्ति','अहंकार, आलोचनामा असहिष्णुता, स्वास्थ्यमा ताप, अस्पष्टता','राज्य, प्रशासन, शिक्षा र नेतृत्व क्षेत्रमा उन्नति, कला','सरकारी स्रोतबाट लाभ, सम्पत्तिमा वृद्धि, स्रोत अनिश्चित','आफ्नो अहम्ले जीवनसाथीसँग द्वन्द्व सिर्जना गर्न सक्छ, निःशर्त प्रेम, बलिदान','सूर्यो लग्नस्थो बलवान् भवति। सूर्यो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 2','रविवार जल अर्पण र सूर्य मन्त्र जप।'),
(1,2,1,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, साहस','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, जल्दबाजी','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, आत्मप्रयासबाट आय','परिवारमा आफ्नो कुरा मान्ने जिद, ऊर्जावान तर धैर्य कम','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,2,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, धैर्य','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, जिद','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, बचत र भूमि लाभ','परिवारमा आफ्नो कुरा मान्ने जिद, वफादार र शान्त','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,3,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, वाणी','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, द्विधा','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, बहुआय, अनियमित','परिवारमा आफ्नो कुरा मान्ने जिद, मैत्रीपूर्ण तर भावना चञ्चल','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,4,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, करुणा','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, मनोद्वन्द्व','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, चल सम्पत्ति, जलजन्य आय','परिवारमा आफ्नो कुरा मान्ने जिद, गहिरो स्नेह र ममता','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,5,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, नेतृत्व','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, दम्भ','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, उदार खर्चसँगै प्रतिष्ठाजनक आय','परिवारमा आफ्नो कुरा मान्ने जिद, आदर चाहने, उदार','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,6,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, विश्लेषण','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, आलोचनात्मकता','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, योजनाबद्ध बचत','परिवारमा आफ्नो कुरा मान्ने जिद, व्यावहारिक स्नेह, सेवा','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,7,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, न्याय','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, निर्णय ढिलाइ','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, सन्तुलित आय','परिवारमा आफ्नो कुरा मान्ने जिद, सामञ्जस्यपूर्ण जीवनसाथी','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,8,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, अन्तर्दृष्टि','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, षड्यन्त्रवाद','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, अचानक उतारचढाव','परिवारमा आफ्नो कुरा मान्ने जिद, गहिरो तर तीव्र','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,9,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, ज्ञान','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, अति विश्वास','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, भाग्यबाट लाभ, उदार खर्च','परिवारमा आफ्नो कुरा मान्ने जिद, स्वतन्त्रता दिने','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,10,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, कर्मठता','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, निराशावाद','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, हौले हौले सम्पत्ति','परिवारमा आफ्नो कुरा मान्ने जिद, जिम्मेवार तर शब्द कम','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,11,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, नवप्रवर्तन','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, विद्रोहीपन','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, नवीन तर अनियमित स्रोत','परिवारमा आफ्नो कुरा मान्ने जिद, मित्रतामा आधारित','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,2,12,'सूर्य दोस्रो भावमा धन संचयकर्ता हुन्छ। आफ्नो परिश्रम र सरकारी स्रोतबाट आय आउँछ। वाणीमा आधिकारिक भाव रहन्छ तर परिवारभित्र अहम् देखिन सक्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'धन संचय, वाणीमा आधिकारिकता, परिवारमा नेतृत्व, उच्च आदर्श, कल्पनाशक्ति','अहंकार, परिवारसँग मतभेद, स्वास्थ्यमा ताप, अस्पष्टता','बैंक, राजकोष, प्रशासन, उद्यम','दीर्घकालीन बचत र सम्पत्ति वृद्धि, स्रोत अनिश्चित, दानशीलता','परिवारमा आफ्नो कुरा मान्ने जिद, निःशर्त प्रेम, बलिदान','सूर्यो द्वितीयस्थो धनवान् भवति। सूर्यो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,3,1,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, नेतृत्व','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, क्रोध','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, आत्मप्रयासबाट आय','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, ऊर्जावान तर धैर्य कम','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो मेषे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,2,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, धैर्य','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, जिद','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, बचत र भूमि लाभ','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, वफादार र शान्त','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो वृषभे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,3,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, वाणी','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, द्विधा','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, बहुआय','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, मैत्रीपूर्ण तर भावना चञ्चल','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो मिथुने फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,4,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, करुणा','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, मनोद्वन्द्व','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, चल सम्पत्ति','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, गहिरो स्नेह र ममता','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो कर्के फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,5,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, नेतृत्व','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, अहंकार','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, उदार खर्चसँगै प्रतिष्ठाजनक आय','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, आदर चाहने','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो सिंहे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,6,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, विश्लेषण','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, आलोचनात्मकता','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, योजनाबद्ध बचत','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, व्यावहारिक स्नेह','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो कन्यायां फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,7,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, न्याय','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, निर्णय ढिलाइ','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, सन्तुलित आय','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, सामञ्जस्यपूर्ण जीवनसाथी','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो तुलायां फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,8,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, अन्तर्दृष्टि','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, षड्यन्त्रवाद','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, अचानक उतारचढाव','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, गहिरो तर तीव्र','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो वृश्चिके फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,9,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, ज्ञान','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, अति विश्वास','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, भाग्यबाट लाभ','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, स्वतन्त्रता दिने','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो धनौ फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,10,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, कर्मठता','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, निराशावाद','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, हौले हौले सम्पत्ति','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, जिम्मेवार तर शब्द कम','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो मकरे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,11,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, नवप्रवर्तन','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, विद्रोहीपन','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, नवीन तर अनियमित स्रोत','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, मित्रतामा आधारित','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो कुम्भे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,3,12,'सूर्य तेस्रो भावमा पराक्रमी र साहसी बनाउँछ। आत्मबलमा विश्वास गरेर सबै काम आफैं गर्ने प्रवृत्ति हुन्छ। छोटो यात्रा र आत्म-प्रयासबाट सफलता मिल्छ, तर भाइबहिनीसँग अहम् टकराव हुन सक्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'साहस, आत्मनिर्भरता, पहलकदमी, भाइबहिनीमा नेतृत्व, कल्पनाशक्ति','अहम् टकराव, जल्दबाजी, छोटो यात्रामा अवरोध, अस्पष्टता','पत्रकारिता, विपणन, सेना, सूचना प्रविधि','आत्मप्रयासबाट स्थिर आय, तर खर्च पनि बढी, स्रोत अनिश्चित','भाइबहिनीसँग प्रतिस्पर्धा, तर आदर पनि, निःशर्त प्रेम','तृतीयस्थः सूर्यो वीर्यवान् भवति। सूर्यो मीने फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र कर्पूर दीप दान।'),
(1,4,1,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, साहस','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, जल्दबाजी','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, आत्मप्रयासबाट आय','पारिवारिक भावनात्मक दूरी, ऊर्जावान तर धैर्य कम','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो मेषे फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,2,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, धैर्य','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, जिद','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, बचत र भूमि लाभ','पारिवारिक भावनात्मक दूरी, वफादार र शान्त','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो वृषभे फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,3,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, वाणी','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, द्विधा','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, बहुआय','पारिवारिक भावनात्मक दूरी, मैत्रीपूर्ण तर भावना चञ्चल','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो मिथुने फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,4,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, करुणा','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, मनोद्वन्द्व','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, चल सम्पत्ति','पारिवारिक भावनात्मक दूरी, गहिरो स्नेह र ममता','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो कर्के फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,5,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, नेतृत्व','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, अहंकार','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, उदार खर्चसँगै प्रतिष्ठाजनक आय','पारिवारिक भावनात्मक दूरी, आदर चाहने, उदार','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो सिंहे फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,6,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, विश्लेषण','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, आलोचनात्मकता','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, योजनाबद्ध बचत','पारिवारिक भावनात्मक दूरी, व्यावहारिक स्नेह, सेवा','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो कन्यायां फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,7,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, न्याय','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, निर्णय ढिलाइ','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, सन्तुलित आय','पारिवारिक भावनात्मक दूरी, सामञ्जस्यपूर्ण जीवनसाथी','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो तुलायां फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,8,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, अन्तर्दृष्टि','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, षड्यन्त्रवाद','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, अचानक उतारचढाव','पारिवारिक भावनात्मक दूरी, गहिरो तर तीव्र','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो वृश्चिके फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,9,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, ज्ञान','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, अति विश्वास','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, भाग्यबाट लाभ','पारिवारिक भावनात्मक दूरी, स्वतन्त्रता दिने','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो धनौ फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,10,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, कर्मठता','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, निराशावाद','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, हौले हौले सम्पत्ति','पारिवारिक भावनात्मक दूरी, जिम्मेवार तर शब्द कम','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो मकरे फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,11,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, नवप्रवर्तन','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, विद्रोहीपन','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, नवीन तर अनियमित स्रोत','पारिवारिक भावनात्मक दूरी, मित्रतामा आधारित','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो कुम्भे फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,4,12,'सूर्य चौथो भावमा घर-परिवारमा असन्तोष र मातासँग भावनात्मक दूरी दिन्छ। भूमि र सम्पत्तिमा ढिलाइपछि सफलता मिल्छ। गाउँ-समाजमा सम्मान तर घरभित्र तनाव रहन सक्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'भूमि र सम्पत्ति, समाजमा सम्मान, घर स्थापना, पछि उन्नति, कल्पनाशक्ति','मातासँग मतभेद, घरमा तनाव, भूमिमा विवाद, अस्पष्टता','भवन निर्माण, भूमि व्यवसाय, प्रशासन, शिक्षा','जग्गा र घरबाट लाभ, तर लगानी ढिलो, स्रोत अनिश्चित','पारिवारिक भावनात्मक दूरी, निःशर्त प्रेम, बलिदान','चतुर्थस्थः सूर्यो गृहसुखप्रदो भवति। सूर्यो मीने फलं वर्धयति।','Brihat Jataka','सूर्यलाई जल अर्पण र घरमा दीप बाल्ने।'),
(1,5,1,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, साहस','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, जल्दबाजी','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, आत्मप्रयासबाट आय','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, ऊर्जावान तर धैर्य कम','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो मेषे फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,2,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, धैर्य','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, जिद','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, बचत र भूमि लाभ','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, वफादार र शान्त','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो वृषभे फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,3,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, वाणी','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, द्विधा','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, बहुआय','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, मैत्रीपूर्ण तर भावना चञ्चल','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो मिथुने फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,4,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, करुणा','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, मनोद्वन्द्व','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, चल सम्पत्ति','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, गहिरो स्नेह र ममता','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो कर्के फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,5,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, नेतृत्व','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, अहंकार','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, आदर चाहने','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो सिंहे फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,6,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, विश्लेषण','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, आलोचनात्मकता','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, योजनाबद्ध बचत','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, व्यावहारिक स्नेह','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो कन्यायां फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,7,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, न्याय','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, निर्णय ढिलाइ','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, सन्तुलित आय','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, सामञ्जस्यपूर्ण जीवनसाथी','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो तुलायां फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,8,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, अन्तर्दृष्टि','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, षड्यन्त्रवाद','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, अचानक उतारचढाव','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, गहिरो तर तीव्र','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो वृश्चिके फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,9,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, ज्ञान','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, अति विश्वास','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, भाग्यबाट लाभ','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, स्वतन्त्रता दिने','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो धनौ फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,10,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, कर्मठता','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, निराशावाद','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, हौले हौले सम्पत्ति','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, जिम्मेवार तर शब्द कम','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो मकरे फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,11,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, नवप्रवर्तन','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, विद्रोहीपन','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, नवीन तर अनियमित स्रोत','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, मित्रतामा आधारित','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो कुम्भे फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,5,12,'सूर्य पाँचौं भावमा बुद्धि र विद्यामा प्रबलता दिन्छ। सन्तानप्रति अपेक्षा बढी रहन्छ र सन्तानले कठिनाइ दिन सक्छ। धार्मिक विचार, शिक्षा र पुण्यबाट सम्मान मिल्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'तीव्र बुद्धि, विद्यामा उत्कृष्टता, धार्मिक प्रवृत्ति, पुण्य बल, कल्पनाशक्ति','सन्तानसँग मतभेद, प्रेममा अहम्, सट्टेबाजीमा हानि, अस्पष्टता','शिक्षण, अनुसन्धान, धार्मिक कार्य, शेयर बजार','अटकलबाजीबाट लाभ-हानि दुवै, पुरानो सम्पत्तिबाट आय, स्रोत अनिश्चित','प्रेममा अहम्, सन्तानसँग गम्भीर सम्बन्ध, निःशर्त प्रेम','पञ्चमस्थः सूर्यो धर्मप्रियो भवति। सूर्यो मीने फलं वर्धयति।','Saravali','सूर्य मन्त्र जप र विद्यार्थीलाई दान गर्ने।'),
(1,6,1,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, साहस','क्रोध, विवाद, पेट र आँखा समस्या, जल्दबाजी','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, ऊर्जावान तर धैर्य कम','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो मेषे फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,2,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, धैर्य','क्रोध, विवाद, पेट र आँखा समस्या, जिद','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, वफादार र शान्त','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो वृषभे फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,3,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, वाणी','क्रोध, विवाद, पेट र आँखा समस्या, द्विधा','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, मैत्रीपूर्ण तर भावना चञ्चल','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो मिथुने फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,4,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, करुणा','क्रोध, विवाद, पेट र आँखा समस्या, मनोद्वन्द्व','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, गहिरो स्नेह र ममता','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो कर्के फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,5,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, नेतृत्व','क्रोध, विवाद, पेट र आँखा समस्या, अहंकार','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, आदर चाहने','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो सिंहे फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,6,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, विश्लेषण','क्रोध, विवाद, पेट र आँखा समस्या, आलोचनात्मकता','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, व्यावहारिक स्नेह','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो कन्यायां फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,7,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, न्याय','क्रोध, विवाद, पेट र आँखा समस्या, निर्णय ढिलाइ','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, सामञ्जस्यपूर्ण जीवनसाथी','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो तुलायां फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,8,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, अन्तर्दृष्टि','क्रोध, विवाद, पेट र आँखा समस्या, षड्यन्त्रवाद','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, गहिरो तर तीव्र','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो वृश्चिके फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,9,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, ज्ञान','क्रोध, विवाद, पेट र आँखा समस्या, अति विश्वास','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, स्वतन्त्रता दिने','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो धनौ फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,10,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, कर्मठता','क्रोध, विवाद, पेट र आँखा समस्या, निराशावाद','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, जिम्मेवार तर शब्द कम','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो मकरे फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,11,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, नवप्रवर्तन','क्रोध, विवाद, पेट र आँखा समस्या, विद्रोहीपन','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, मित्रतामा आधारित','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो कुम्भे फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,6,12,'सूर्य छैटौं भावमा शत्रुलाई परास्त गर्ने शक्ति दिन्छ। रोग प्रतिरोधात्मक क्षमता बलियो हुन्छ। सेवा र प्रशासनमा प्रतिष्ठा पाउँछ, तर कहिलेकाहीँ क्रोध र अहंकारले विवाद बढाउँछ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'शत्रु पराजय, रोग प्रतिरोध, सेवामा प्रतिष्ठा, प्रशासनिक क्षमता, कल्पनाशक्ति','क्रोध, विवाद, पेट र आँखा समस्या, अस्पष्टता','प्रशासन, चिकित्सा, वकालत, सुरक्षा','ऋण फिर्ता, नियमित आय, तर विवादमा खर्च','सहकर्मीसँग तनाव, सेवाभावी मित्र, निःशर्त प्रेम','सूर्यो षष्ठस्थो रिपुं जयति। सूर्यो मीने फलं वर्धयति।','Phaladeepika','रविवार तिल-तेल दान र सूर्य मन्त्र जप।'),
(1,7,1,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, साहस, नेतृत्व','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, जल्दबाजी','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, सेना, खेलकुद','साझेदारीबाट आय, तर विवादले हानि पनि, आत्मप्रयासबाट आय','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, ऊर्जावान तर धैर्य कम','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,2,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, धैर्य, संचय','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, जिद','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, कृषि, बैंक','साझेदारीबाट आय, तर विवादले हानि पनि, बचत र भूमि लाभ','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, वफादार र शान्त','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,3,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, वाणी, बुद्धि','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, द्विधा','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, लेखन, सञ्चार','साझेदारीबाट आय, तर विवादले हानि पनि, बहुआय','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, मैत्रीपूर्ण तर भावना चञ्चल','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,4,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, करुणा, स्मृति','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, मनोद्वन्द्व','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, खाद्य, शिक्षा','साझेदारीबाट आय, तर विवादले हानि पनि, चल सम्पत्ति','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, गहिरो स्नेह र ममता','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,5,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, नेतृत्व, दानशीलता','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, अहंकार','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, प्रशासन, कला','साझेदारीबाट आय, तर विवादले हानि पनि, उदार खर्चसँगै प्रतिष्ठाजनक आय','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, आदर चाहने, उदार','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,6,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, विश्लेषण, शुद्धता','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, आलोचनात्मकता','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, चिकित्सा, लेखा','साझेदारीबाट आय, तर विवादले हानि पनि, योजनाबद्ध बचत','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, व्यावहारिक स्नेह, सेवा','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,7,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, न्याय, सौन्दर्य','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, निर्णय ढिलाइ','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, कानुन, कला','साझेदारीबाट आय, तर विवादले हानि पनि, सन्तुलित आय','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, सामञ्जस्यपूर्ण जीवनसाथी','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,8,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, अन्तर्दृष्टि, परिवर्तन','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, षड्यन्त्रवाद','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, अनुसन्धान, सुरक्षा','साझेदारीबाट आय, तर विवादले हानि पनि, अचानक उतारचढाव','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, गहिरो तर तीव्र','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,9,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, ज्ञान, आशावाद','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, अति विश्वास','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, शिक्षण, धर्म','साझेदारीबाट आय, तर विवादले हानि पनि, भाग्यबाट लाभ','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, स्वतन्त्रता दिने','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,10,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, कर्मठता, धैर्य','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, निराशावाद','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, प्रशासन, व्यवस्थापन','साझेदारीबाट आय, तर विवादले हानि पनि, हौले हौले सम्पत्ति','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, जिम्मेवार तर शब्द कम','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,11,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, नवप्रवर्तन, मित्रता','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, विद्रोहीपन','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, प्रविधि, विज्ञान','साझेदारीबाट आय, तर विवादले हानि पनि, नवीन तर अनियमित स्रोत','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, मित्रतामा आधारित','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,7,12,'सूर्य सप्तम भावमा वैवाहिक जीवनमा अहम् कारक हुन्छ। जीवनसाथीसँग आत्ममहत्वको टकराव हुन्छ तर जीवनसाथी बलिया र प्रतिष्ठित हुन्छन्। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'जीवनसाथीको प्रतिष्ठा, साझेदारीमा अधिकार, सार्वजनिक मान्यता, कल्पनाशक्ति, करुणा','अहम् टकराव, विवाद, साझेदारीमा द्वन्द्व, अस्पष्टता','सरकारी वा उच्च पदको जीवनसाथी, व्यापारमा स्थापना, कला, सेवा','साझेदारीबाट आय, तर विवादले हानि पनि, स्रोत अनिश्चित','विवाहमा ढिला वा विवाद पछि सामञ्जस्य, निःशर्त प्रेम, बलिदान','सप्तमस्थः सूर्यो द्वन्द्वावहः। सूर्यो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 12','शनिवार तिल तेल दान र सूर्य मन्त्र जप।'),
(1,8,1,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, साहस','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, जल्दबाजी','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, आत्मप्रयासबाट आय','गोपनीयता र भावनात्मक दूरी, ऊर्जावान तर धैर्य कम','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,2,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, धैर्य','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, जिद','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, बचत र भूमि लाभ','गोपनीयता र भावनात्मक दूरी, वफादार र शान्त','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,3,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, वाणी','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, द्विधा','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, बहुआय','गोपनीयता र भावनात्मक दूरी, मैत्रीपूर्ण तर भावना चञ्चल','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,4,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, करुणा','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, मनोद्वन्द्व','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, चल सम्पत्ति','गोपनीयता र भावनात्मक दूरी, गहिरो स्नेह र ममता','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,5,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, नेतृत्व','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, अहंकार','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','गोपनीयता र भावनात्मक दूरी, आदर चाहने, उदार','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,6,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, विश्लेषण','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, आलोचनात्मकता','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, योजनाबद्ध बचत','गोपनीयता र भावनात्मक दूरी, व्यावहारिक स्नेह, सेवा','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,7,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, न्याय','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, निर्णय ढिलाइ','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, सन्तुलित आय','गोपनीयता र भावनात्मक दूरी, सामञ्जस्यपूर्ण जीवनसाथी','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,8,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, अन्तर्दृष्टि','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, षड्यन्त्रवाद','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, अचानक उतारचढाव','गोपनीयता र भावनात्मक दूरी, गहिरो तर तीव्र','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,9,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, ज्ञान','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, अति विश्वास','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, भाग्यबाट लाभ','गोपनीयता र भावनात्मक दूरी, स्वतन्त्रता दिने','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,10,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, कर्मठता','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, निराशावाद','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, हौले हौले सम्पत्ति','गोपनीयता र भावनात्मक दूरी, जिम्मेवार तर शब्द कम','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,11,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, नवप्रवर्तन','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, विद्रोहीपन','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, नवीन तर अनियमित स्रोत','गोपनीयता र भावनात्मक दूरी, मित्रतामा आधारित','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,8,12,'सूर्य आउठौं भावमा जीवनमा उतार-चढाव र अचानक परिवर्तन ल्याउँछ। आयु र स्वास्थ्यमा सावधानी चाहिन्छ। रहस्य र अनुसन्धानमा रुचि बढ्छ, छानबिन र विरासतबाट लाभ हुन सक्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'अनुसन्धान क्षमता, रहस्य ज्ञान, आकस्मिक उन्नति, दीर्घायु पछिको बल, कल्पनाशक्ति','अचानक परिवर्तन, स्वास्थ्य जोखिम, सत्ता संघर्ष, अस्पष्टता','अनुसन्धान, कर र लेखा, चिकित्सा, गुप्तचरी','अनपेक्षित लाभ-हानि, विरासत र बीमाबाट आय, स्रोत अनिश्चित','गोपनीयता र भावनात्मक दूरी, निःशर्त प्रेम, बलिदान','अष्टमस्थः सूर्यो आयुर्दायी भवति। सूर्यो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra','सूर्यलाई जल अर्पण र गंगाजल दान गर्ने।'),
(1,9,1,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, साहस','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, जल्दबाजी','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, आत्मप्रयासबाट आय','गुरु र पितासँग गहिरो सम्बन्ध, ऊर्जावान तर धैर्य कम','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो मेषे फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,2,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, धैर्य','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, जिद','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, बचत र भूमि लाभ','गुरु र पितासँग गहिरो सम्बन्ध, वफादार र शान्त','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो वृषभे फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,3,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, वाणी','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, द्विधा','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, बहुआय','गुरु र पितासँग गहिरो सम्बन्ध, मैत्रीपूर्ण तर भावना चञ्चल','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो मिथुने फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,4,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, करुणा','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, मनोद्वन्द्व','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, चल सम्पत्ति','गुरु र पितासँग गहिरो सम्बन्ध, गहिरो स्नेह र ममता','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो कर्के फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,5,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, नेतृत्व','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, अहंकार','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, उदार खर्चसँगै प्रतिष्ठाजनक आय','गुरु र पितासँग गहिरो सम्बन्ध, आदर चाहने, उदार','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो सिंहे फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,6,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, विश्लेषण','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, आलोचनात्मकता','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, योजनाबद्ध बचत','गुरु र पितासँग गहिरो सम्बन्ध, व्यावहारिक स्नेह, सेवा','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो कन्यायां फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,7,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, न्याय','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, निर्णय ढिलाइ','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, सन्तुलित आय','गुरु र पितासँग गहिरो सम्बन्ध, सामञ्जस्यपूर्ण जीवनसाथी','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो तुलायां फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,8,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, अन्तर्दृष्टि','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, षड्यन्त्रवाद','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, अचानक उतारचढाव','गुरु र पितासँग गहिरो सम्बन्ध, गहिरो तर तीव्र','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो वृश्चिके फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,9,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, ज्ञान','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, अति विश्वास','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, भाग्यबाट लाभ','गुरु र पितासँग गहिरो सम्बन्ध, स्वतन्त्रता दिने','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो धनौ फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,10,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, कर्मठता','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, निराशावाद','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, हौले हौले सम्पत्ति','गुरु र पितासँग गहिरो सम्बन्ध, जिम्मेवार तर शब्द कम','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो मकरे फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,11,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, नवप्रवर्तन','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, विद्रोहीपन','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, नवीन तर अनियमित स्रोत','गुरु र पितासँग गहिरो सम्बन्ध, मित्रतामा आधारित','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो कुम्भे फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,9,12,'सूर्य नवौं भावमा धर्म र भाग्यलाई बलियो बनाउँछ। पिता र गुरुको स्नेह मिल्छ। उच्च शिक्षा, तीर्थ र आध्यात्मिक कार्यबाट मान-सम्मान बढ्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'भाग्य बल, धर्म प्रवृत्ति, पिताको स्नेह, उच्च शिक्षा, कल्पनाशक्ति','पितासँग दूरी, धर्ममा औपचारिकता, ढिलो भाग्योदय, अस्पष्टता','शिक्षा, धर्म प्रचार, न्याय, सरकारी सेवा','भाग्यले अप्रत्याशित स्रोत, दानबाट वृद्धि, स्रोत अनिश्चित','गुरु र पितासँग गहिरो सम्बन्ध, निःशर्त प्रेम, बलिदान','नवमस्थः सूर्यो भाग्यवान् भवति। सूर्यो मीने फलं वर्धयति।','Brihat Jataka','सूर्यलाई अर्घ्य दिई गुरु वन्दना गर्ने।'),
(1,10,1,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, साहस','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, जल्दबाजी, क्रोध','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, आत्मप्रयासबाट आय','कर्म प्रधान हुँदा परिवारमा कम समय, ऊर्जावान तर धैर्य कम','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,2,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, धैर्य','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, जिद, अति संग्रह','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, बचत र भूमि लाभ','कर्म प्रधान हुँदा परिवारमा कम समय, वफादार र शान्त','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,3,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, वाणी','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, द्विधा, अस्थिरता','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, बहुआय, अनियमित','कर्म प्रधान हुँदा परिवारमा कम समय, मैत्रीपूर्ण तर भावना चञ्चल','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,4,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, करुणा','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, मनोद्वन्द्व, कुढ्ने स्वभाव','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, चल सम्पत्ति, जलजन्य आय','कर्म प्रधान हुँदा परिवारमा कम समय, गहिरो स्नेह र ममता','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,5,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, नेतृत्व','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, अहंकार, दम्भ','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, उदार खर्चसँगै प्रतिष्ठाजनक आय','कर्म प्रधान हुँदा परिवारमा कम समय, आदर चाहने, उदार','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,6,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, विश्लेषण','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, आलोचनात्मकता, चिन्ता','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, योजनाबद्ध बचत','कर्म प्रधान हुँदा परिवारमा कम समय, व्यावहारिक स्नेह, सेवा','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,7,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, न्याय','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, निर्णय ढिलाइ, अति सम्झौता','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, सन्तुलित आय','कर्म प्रधान हुँदा परिवारमा कम समय, सामञ्जस्यपूर्ण जीवनसाथी','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,8,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, अन्तर्दृष्टि','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, षड्यन्त्रवाद, अति गोपन','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, अचानक उतारचढाव','कर्म प्रधान हुँदा परिवारमा कम समय, गहिरो तर तीव्र','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,9,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, ज्ञान','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, अति विश्वास, उद्देश्य भ्रम','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, भाग्यबाट लाभ, उदार खर्च','कर्म प्रधान हुँदा परिवारमा कम समय, स्वतन्त्रता दिने','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,10,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, कर्मठता','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, निराशावाद, कठोरता','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, हौले हौले सम्पत्ति','कर्म प्रधान हुँदा परिवारमा कम समय, जिम्मेवार तर शब्द कम','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,11,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, नवप्रवर्तन','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, विद्रोहीपन, भावनात्मक टाढा','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, नवीन तर अनियमित स्रोत','कर्म प्रधान हुँदा परिवारमा कम समय, मित्रतामा आधारित','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,10,12,'सूर्य दसौं भावमा कर्म क्षेत्रमा उच्च पद दिने कारक हो। सरकार, प्रशासन र नेतृत्व क्षेत्रमा ख्याति प्राप्त हुन्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'पद, प्रतिष्ठा, अधिकार, सार्वजनिक सफलता, कल्पनाशक्ति','अहंकारले अधिनायकता, सहकर्मीसँग तनाव, अस्पष्टता, भाग्यमा अति निर्भरता','राज्यसेवा, प्रशासन, शासन, शिक्षामा उच्च पद','नियमित आय र सरकारी स्रोतबाट लाभ, स्रोत अनिश्चित, दानशीलता','कर्म प्रधान हुँदा परिवारमा कम समय, निःशर्त प्रेम, बलिदान','सूर्यो दशमे राज्यप्रियो भवति। सूर्यो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 19','रविवार सूर्यलाई जल अर्पण गर्ने।'),
(1,11,1,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, साहस','लोभ, मित्रसँग अहम्, अति आशावाद, जल्दबाजी','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, आत्मप्रयासबाट आय','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, ऊर्जावान तर धैर्य कम','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो मेषे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,2,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, धैर्य','लोभ, मित्रसँग अहम्, अति आशावाद, जिद','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, बचत र भूमि लाभ','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, वफादार र शान्त','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो वृषभे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,3,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, वाणी','लोभ, मित्रसँग अहम्, अति आशावाद, द्विधा','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, बहुआय','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, मैत्रीपूर्ण तर भावना चञ्चल','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो मिथुने फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,4,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, करुणा','लोभ, मित्रसँग अहम्, अति आशावाद, मनोद्वन्द्व','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, चल सम्पत्ति','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, गहिरो स्नेह र ममता','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो कर्के फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,5,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, नेतृत्व','लोभ, मित्रसँग अहम्, अति आशावाद, अहंकार','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, उदार खर्चसँगै प्रतिष्ठाजनक आय','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, आदर चाहने','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो सिंहे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,6,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, विश्लेषण','लोभ, मित्रसँग अहम्, अति आशावाद, आलोचनात्मकता','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, योजनाबद्ध बचत','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, व्यावहारिक स्नेह','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो कन्यायां फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,7,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, न्याय','लोभ, मित्रसँग अहम्, अति आशावाद, निर्णय ढिलाइ','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, सन्तुलित आय','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, सामञ्जस्यपूर्ण जीवनसाथी','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो तुलायां फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,8,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, अन्तर्दृष्टि','लोभ, मित्रसँग अहम्, अति आशावाद, षड्यन्त्रवाद','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, अचानक उतारचढाव','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, गहिरो तर तीव्र','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो वृश्चिके फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,9,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, ज्ञान','लोभ, मित्रसँग अहम्, अति आशावाद, अति विश्वास','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, भाग्यबाट लाभ','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, स्वतन्त्रता दिने','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो धनौ फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,10,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, कर्मठता','लोभ, मित्रसँग अहम्, अति आशावाद, निराशावाद','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, हौले हौले सम्पत्ति','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, जिम्मेवार तर शब्द कम','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो मकरे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,11,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, नवप्रवर्तन','लोभ, मित्रसँग अहम्, अति आशावाद, विद्रोहीपन','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, नवीन तर अनियमित स्रोत','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, मित्रतामा आधारित','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो कुम्भे फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,11,12,'सूर्य एघारौं भावमा आय र लाभको कारक हुन्छ। उच्च पदका व्यक्ति र पुराना सम्बन्धबाट सहयोग मिल्छ। आकांक्षा पूरा हुन्छ तर लोभमा परे लाभ घट्न सक्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'आय वृद्धि, इच्छा पूर्ति, प्रभावशाली मित्र, उच्च पदको सहयोग, कल्पनाशक्ति','लोभ, मित्रसँग अहम्, अति आशावाद, अस्पष्टता','व्यापार, प्रबन्धन, राजनीति, नेटवर्किङ','नियमित लाभ र बोनस, निवेशबाट आम्दानी, स्रोत अनिश्चित','विस्तृत मित्रचक्र, परिवारसँग लाभ साझेदारी, निःशर्त प्रेम','एकादशस्थः सूर्यो लाभकृत् भवति। सूर्यो मीने फलं वर्धयति।','Phaladeepika','रविवार सूर्य मन्त्र जप र ज्येष्ठलाई सम्मान गर्ने।'),
(1,12,1,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको मेष राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, साहस','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, जल्दबाजी','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, ऊर्जावान तर धैर्य कम','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो मेषे फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,2,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको वृषभ राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, धैर्य','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, जिद','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, वफादार र शान्त','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो वृषभे फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,3,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको मिथुन राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, वाणी','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, द्विधा','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, मैत्रीपूर्ण तर भावना चञ्चल','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो मिथुने फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,4,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको कर्क राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, करुणा','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, मनोद्वन्द्व','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, गहिरो स्नेह र ममता','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो कर्के फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,5,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको सिंह राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, नेतृत्व','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, अहंकार','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, आदर चाहने, उदार','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो सिंहे फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,6,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको कन्या राशिसँग शत्रु सम्बन्धले यो फल प्रतिकूल र चुनौतीपूर्ण बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, विश्लेषण','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, आलोचनात्मकता','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, व्यावहारिक स्नेह, सेवा','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो कन्यायां फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,7,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको तुला राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, न्याय','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, निर्णय ढिलाइ','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, सामञ्जस्यपूर्ण जीवनसाथी','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो तुलायां फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,8,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको वृश्चिक राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, अन्तर्दृष्टि','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, षड्यन्त्रवाद','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, गहिरो तर तीव्र','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो वृश्चिके फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,9,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, ज्ञान','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, अति विश्वास','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, स्वतन्त्रता दिने','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो धनौ फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,10,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, कर्मठता','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, निराशावाद','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, जिम्मेवार तर शब्द कम','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो मकरे फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,11,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, नवप्रवर्तन','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, विद्रोहीपन','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, मित्रतामा आधारित','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो कुम्भे फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(1,12,12,'सूर्य बाह्रौं भावमा खर्च र विदेशसँग जोडिन्छ। सरकारी र विदेशी स्रोतबाट खर्च हुन्छ तर अन्ततः मुक्तिको मार्ग देखाउँछ। नेत्र र निद्रामा सावधानी राख्नुपर्छ। सूर्यको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'विदेश वास, आध्यात्मिक उन्नति, मोक्ष मार्ग, गोपनीय स्रोतबाट लाभ, कल्पनाशक्ति','अनावश्यक खर्च, निद्रा समस्या, नेत्र पीडा, अस्पष्टता','विदेशी संस्था, अस्पताल, आश्रम, विश्राम केन्द्र','खर्च बढी, बचत ढिलो, विदेशबाट आय','परिवारबाट टाढा रहने अवस्था, निःशर्त प्रेम, बलिदान','द्वादशस्थः सूर्यो मोक्षमार्गं दर्शयति। सूर्यो मीने फलं वर्धयति।','Saravali','सूर्यलाई जल अर्पण र नियमित ध्यान गर्ने।'),
(2,1,1,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, साहस','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, जल्दबाजी','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, आत्मप्रयासबाट आय','भावनात्मक जीवनसाथी, माया गहिरो, ऊर्जावान तर धैर्य कम','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,2,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको वृषभ राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, धैर्य','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, जिद','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, बचत र भूमि लाभ','भावनात्मक जीवनसाथी, माया गहिरो, वफादार र शान्त','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,3,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको मिथुन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, वाणी','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, द्विधा','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, बहुआय','भावनात्मक जीवनसाथी, माया गहिरो, मैत्रीपूर्ण तर भावना चञ्चल','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,4,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको कर्क राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, करुणा','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, मनोद्वन्द्व','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, चल सम्पत्ति','भावनात्मक जीवनसाथी, माया गहिरो, गहिरो स्नेह र ममता','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,5,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, नेतृत्व','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, अहंकार','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','भावनात्मक जीवनसाथी, माया गहिरो, आदर चाहने','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,6,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको कन्या राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, विश्लेषण','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, आलोचनात्मकता','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, योजनाबद्ध बचत','भावनात्मक जीवनसाथी, माया गहिरो, व्यावहारिक स्नेह','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,7,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, न्याय','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, निर्णय ढिलाइ','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, सन्तुलित आय','भावनात्मक जीवनसाथी, माया गहिरो, सामञ्जस्यपूर्ण जीवनसाथी','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,8,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको वृश्चिक राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, अन्तर्दृष्टि','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, षड्यन्त्रवाद','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, अचानक उतारचढाव','भावनात्मक जीवनसाथी, माया गहिरो, गहिरो तर तीव्र','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,9,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, ज्ञान','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, अति विश्वास','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, भाग्यबाट लाभ','भावनात्मक जीवनसाथी, माया गहिरो, स्वतन्त्रता दिने','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,10,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, कर्मठता','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, निराशावाद','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, हौले हौले सम्पत्ति','भावनात्मक जीवनसाथी, माया गहिरो, जिम्मेवार तर शब्द कम','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,11,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, नवप्रवर्तन','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, विद्रोहीपन','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, नवीन तर अनियमित स्रोत','भावनात्मक जीवनसाथी, माया गहिरो, मित्रतामा आधारित','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,1,12,'चन्द्र लग्नमा व्यक्ति संवेदनशील, कलात्मक र लोकप्रिय हुन्छ। चेहरा गोलाकार र आँखा आकर्षक हुन्छन्। मन भावनाप्रधान हुन्छ। चन्द्रको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'चाक्षुष आकर्षण, लोकप्रियता, कलात्मक प्रतिभा, मातृ स्नेह, कल्पनाशक्ति','मन चञ्चलता, भावनामा अस्थिरता, निर्णय ढिला, अस्पष्टता','कला, सञ्चार, जनसम्पर्क, खाद्य उद्योग','जल र पर्यटनबाट लाभ, परिवर्तनशील आय, स्रोत अनिश्चित','भावनात्मक जीवनसाथी, माया गहिरो, निःशर्त प्रेम','चन्द्रो लग्ने सौम्यवद् भवति। चन्द्रो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra, Adhyaya 3','सोमबार शिवलिंगमा जल चढाउने।'),
(2,2,1,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, साहस','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, जल्दबाजी','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, आत्मप्रयासबाट आय','परिवारसँग गहिरो भावनात्मक जडान, ऊर्जावान तर धैर्य कम','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो मेषे फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,2,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको वृषभ राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, धैर्य','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, जिद','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, बचत र भूमि लाभ','परिवारसँग गहिरो भावनात्मक जडान, वफादार र शान्त','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो वृषभे फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,3,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको मिथुन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, वाणी','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, द्विधा','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, बहुआय, अनियमित','परिवारसँग गहिरो भावनात्मक जडान, मैत्रीपूर्ण तर भावना चञ्चल','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो मिथुने फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,4,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको कर्क राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, करुणा','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, मनोद्वन्द्व','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, चल सम्पत्ति, जलजन्य आय','परिवारसँग गहिरो भावनात्मक जडान, गहिरो स्नेह र ममता','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो कर्के फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,5,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, नेतृत्व','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, अहंकार','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, उदार खर्चसँगै प्रतिष्ठाजनक आय','परिवारसँग गहिरो भावनात्मक जडान, आदर चाहने, उदार','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो सिंहे फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,6,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको कन्या राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, विश्लेषण','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, आलोचनात्मकता','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, योजनाबद्ध बचत','परिवारसँग गहिरो भावनात्मक जडान, व्यावहारिक स्नेह, सेवा','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो कन्यायां फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,7,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, न्याय','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, निर्णय ढिलाइ','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, सन्तुलित आय','परिवारसँग गहिरो भावनात्मक जडान, सामञ्जस्यपूर्ण जीवनसाथी','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो तुलायां फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,8,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको वृश्चिक राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, अन्तर्दृष्टि','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, षड्यन्त्रवाद','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, अचानक उतारचढाव','परिवारसँग गहिरो भावनात्मक जडान, गहिरो तर तीव्र','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो वृश्चिके फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,9,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, ज्ञान','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, अति विश्वास','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, भाग्यबाट लाभ, उदार खर्च','परिवारसँग गहिरो भावनात्मक जडान, स्वतन्त्रता दिने','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो धनौ फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,10,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, कर्मठता','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, निराशावाद','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, हौले हौले सम्पत्ति','परिवारसँग गहिरो भावनात्मक जडान, जिम्मेवार तर शब्द कम','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो मकरे फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,11,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, नवप्रवर्तन','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, विद्रोहीपन','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, नवीन तर अनियमित स्रोत','परिवारसँग गहिरो भावनात्मक जडान, मित्रतामा आधारित','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो कुम्भे फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,2,12,'चन्द्र दोस्रो भावमा धन र परिवारमा स्नेह दिन्छ। माता र जनसम्पर्कबाट आय आउँछ। मिठो वाणी हुन्छ तर भावनाप्रधान खर्चले बचत उतार-चढाव गराउँछ। चन्द्रको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'मिठो वाणी, परिवार प्रेम, जनसम्पर्कबाट आय, कलात्मकता, कल्पनाशक्ति','भावनाप्रधान खर्च, उतार-चढाव, मानसिक चिन्ता, अस्पष्टता','जनसम्पर्क, परामर्श, दृश्य कला, जल सम्बन्धी व्यवसाय','उतार-चढाव भए पनि परिवारबाट लाभ, स्रोत अनिश्चित, दानशीलता','परिवारसँग गहिरो भावनात्मक जडान, निःशर्त प्रेम, बलिदान','चन्द्रो द्वितीयस्थो धनवान् भवति। चन्द्रो मीने फलं वर्धयति।','Brihat Parashara Hora Shastra','सोमवार चन्द्रलाई जल अर्पण गर्ने।'),
(2,3,1,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, नेतृत्व','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, जल्दबाजी','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, आत्मप्रयासबाट आय','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, ऊर्जावान तर धैर्य कम','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो मेषे फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,2,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको वृषभ राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, धैर्य','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, जिद','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, बचत र भूमि लाभ','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, वफादार र शान्त','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो वृषभे फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,3,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको मिथुन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मिथुन राशिको चञ्चल र सञ्चारी स्वभावले वाणी र सम्बन्धमा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, वाणी','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, द्विधा','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, बहुआय','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, मैत्रीपूर्ण तर भावना चञ्चल','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो मिथुने फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,4,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको कर्क राशिसँग स्वकीय सम्बन्धले यो फल सुदृढ बनाउँछ। कर्क राशिको भावनात्मक र पोषक स्वभावले परिवार र सुरक्षामा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, करुणा','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, मनोद्वन्द्व','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, चल सम्पत्ति','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, गहिरो स्नेह र ममता','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो कर्के फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,5,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको सिंह राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। सिंह राशिको राजसी र आत्मविश्वासी स्वभावले प्रतिष्ठा र नेतृत्वमा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, नेतृत्व','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, अहंकार','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, उदार खर्चसँगै प्रतिष्ठाजनक आय','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, आदर चाहने, उदार','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो सिंहे फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,6,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको कन्या राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कन्या राशिको विश्लेषक र सेवाभावी स्वभावले सेवा र व्यवस्थापनमा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, विश्लेषण','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, आलोचनात्मकता','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, योजनाबद्ध बचत','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, व्यावहारिक स्नेह, सेवा','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो कन्यायां फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,7,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको तुला राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। तुला राशिको सन्तुलित र कलात्मक स्वभावले न्याय र सामञ्जस्यमा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, न्याय','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, निर्णय ढिलाइ','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, सन्तुलित आय','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, सामञ्जस्यपूर्ण जीवनसाथी','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो तुलायां फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,8,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको वृश्चिक राशिसँग नीच सम्बन्धले यो फल दुर्बल र बाधापूर्ण बनाउँछ। वृश्चिक राशिको तीव्र र अनुसन्धानी स्वभावले अन्तर्दृष्टि र परिवर्तनमा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, अन्तर्दृष्टि','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, षड्यन्त्रवाद','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, अचानक उतारचढाव','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, गहिरो तर तीव्र','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो वृश्चिके फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,9,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको धनु राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। धनु राशिको धार्मिक र जिज्ञासु स्वभावले ज्ञान र यात्रामा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, ज्ञान','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, अति विश्वास','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, भाग्यबाट लाभ','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, स्वतन्त्रता दिने','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो धनौ फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,10,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको मकर राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मकर राशिको अनुशासित र धैर्यवान स्वभावले कर्म र उन्नतिमा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, कर्मठता','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, निराशावाद','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, हौले हौले सम्पत्ति','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, जिम्मेवार तर शब्द कम','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो मकरे फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,11,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको कुम्भ राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। कुम्भ राशिको वैज्ञानिक र विद्रोही स्वभावले नवप्रवर्तन र मित्रतामा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, नवप्रवर्तन','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, विद्रोहीपन','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, नवीन तर अनियमित स्रोत','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, मित्रतामा आधारित','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो कुम्भे फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,3,12,'चन्द्र तेस्रो भावमा कल्पनाशील र साहसी बनाउँछ। छोटो यात्रामा भावनात्मक सुख मिल्छ। भाइबहिनीप्रति स्नेह रहन्छ तर कहिलेकाहीँ मनमैयाबाट काम अधुरो हुन्छ। चन्द्रको मीन राशिसँग सामान्य सम्बन्धले यो फल सामान्य र सन्तुलित बनाउँछ। मीन राशिको करुणामय र आध्यात्मिक स्वभावले करुणा र कल्पनामा विशेष झलक देखिन्छ।',NULL,'कल्पनाशक्ति, साहस, भाइबहिनी स्नेह, यात्रा सुख, करुणा','मनमैया, अधुरो काम, भावनात्मक अस्थिरता, अस्पष्टता','सिनेमा, लेखन, विपणन, पर्यटन','लघु यात्राबाट लाभ, तर अनियमित आय, स्रोत अनिश्चित','भाइबहिनी र छिमेकीसँग स्नेहपूर्ण सम्बन्ध, निःशर्त प्रेम, बलिदान','तृतीयस्थो चन्द्रो बुद्धिमान् भवति। चन्द्रो मीने फलं वर्धयति।','Phaladeepika','सोमवार चन्द्र मन्त्र जप र जलार्पण गर्ने।'),
(2,4,1,'चन्द्र चौथो भावमा आनन्द र शान्तिको कारक हुन्छ। माताको स्नेह र सुन्दर घर-वाहन सुख मिल्छ। भावनात्मक रूपमा शान्त रहन्छ तर कहिलेकाहीँ चिन्ताले मन डोलाउँछ। चन्द्रको मेष राशिसँग मित्र सम्बन्धले यो फल अनुकूल बनाउँछ। मेष राशिको साहसी र ऊर्जावान स्वभावले नेतृत्व र पहलकदमीमा विशेष झलक देखिन्छ।',NULL,'घर सुख, माताको स्नेह, वाहन सुख, भावनात्मक शान्ति, साहस','चिन्ता, घरमा उतार-चढाव, मन डोलने प्रवृत्ति, जल्दबाजी','भवन सजावट, परामर्श, कृषि, जल सम्बन्ध','घर-जग्गाबाट लाभ, बचत भावनाप्रधान, आत्मप्रयासबाट आय','माता र परिवारसँग गहिरो माया, ऊर्जावान तर धैर्य कम','चतुर्थस्थो चन्द्रो सुखदो भवति। चन्द्रो मेषे फलं वर्धयति।','Brihat Jataka','सोमवार चन्द्रलाई जल अर्पण र श्वेत वस्त्र दान।'),
(2,4,2,'चन्द्र चौथो भावमा आनन्द र शान्तिको कारक हुन्छ। माताको स्नेह र सुन्दर घर-वाहन सुख मिल्छ। भावनात्मक रूपमा शान्त रहन्छ तर कहिलेकाहीँ चिन्ताले मन डोलाउँछ। चन्द्रको वृषभ राशिसँग उच्च सम्बन्धले यो फल अति बलियो र शुभ बनाउँछ। वृषभ राशिको स्थिर र व्यावहारिक स्वभावले संचय र स्थिरतामा विशेष झलक देखिन्छ।',NULL,'घर सुख, माताको स्नेह, वाहन सुख, भावनात्मक शान्ति, धैर्य','चिन्ता, घरमा उतार-चढाव, मन डोलने प्रवृत्ति, जिद','भवन सजावट, परामर्श, कृषि, जल सम्बन्ध','घर-जग्गाबाट लाभ, बचत भावनाप्रधान, बचत र भूमि लाभ','माता र परिवारसँग गहिरो माया, वफादार र शान्त','चतुर्थस्थो चन्द्रो सुखदो भवति। चन्द्रो वृषभे फलं वर्धयति।','Brihat Jataka','सोमवार चन्द्रलाई जल अर्पण र श्वेत वस्त्र दान।'),
